pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public {
        c = new demo();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        vm.assume(tos.length > 0);
        for (uint256 i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != address(0));
        }

        Recorder rec = new Recorder();

        vm.prank(from);
        c.transfer(from, address(rec), tos, v);

        assertTrue(rec.callCount() == tos.length);
    }
}

contract Recorder {
    uint256 public callCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        callCount++;
        return true;
    }

    fallback() external payable {}
}
